import { CourseArtifactView } from "@/components/course-artifact-view";

type PageContext = { params: Promise<{ courseId: string; artifactId: string }> };

/**
 * Course-level render view for quizzes and decks generated by the course
 * chat. Artifacts live at course scope (`notebook_id` null) and open from
 * the sidebar under their course.
 */
export default async function CourseStudyPage({ params }: PageContext) {
  const { courseId, artifactId } = await params;
  return <CourseArtifactView courseId={courseId} artifactId={artifactId} />;
}
